<script setup>
import { computed, reactive } from 'vue'
import ActionDialog from '@/Components/Portal/ActionDialog.vue'
import { router, useForm } from '@inertiajs/vue3'
import PortalLayout from '@/Layouts/PortalLayout.vue'
const props=defineProps({doctor:Object,organizations:Array,members:Array,attendances:Array,schedules:Array,todayAttendances:Array,auditEvents:Array,leaveRequests:Array,holidays:Array,absenceRows:Array,summary:Object,month:String,currentUserId:Number,canManage:Boolean})
const organizationId=useForm({organization_id:props.organizations?.[0]?.id??'',clinic_id:''})
const scheduleForm=useForm({organization_id:props.organizations?.find(o=>o.can_manage)?.id??'',clinic_id:'',staff_user_id:'',weekday:0,start_time:'08:00',end_time:'16:00',break_minutes:30,grace_minutes:10,effective_from:new Date().toISOString().slice(0,10),effective_until:''})
const leaveForm=useForm({organization_id:props.organizations?.[0]?.id??'',clinic_id:'',leave_type:'annual',start_date:new Date().toISOString().slice(0,10),end_date:new Date().toISOString().slice(0,10),reason:''})
const holidayForm=useForm({organization_id:props.organizations?.find(o=>o.can_manage)?.id??'',holiday_date:new Date().toISOString().slice(0,10),name:''})
const activeOrg=computed(()=>props.organizations.find(o=>String(o.id)===String(organizationId.organization_id)))
const scheduleOrg=computed(()=>props.organizations.find(o=>String(o.id)===String(scheduleForm.organization_id)))
const leaveOrg=computed(()=>props.organizations.find(o=>String(o.id)===String(leaveForm.organization_id)))
const holidayOrg=computed(()=>props.organizations.find(o=>String(o.id)===String(holidayForm.organization_id)))
const todayRecord=computed(()=>props.todayAttendances.find(a=>String(a.organization_id)===String(organizationId.organization_id)&&String(a.clinic_id)===String(organizationId.clinic_id)))
const fmt=v=>v?new Date(String(v).replace(' ','T')).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}):'—'
const minutes=v=>Math.floor(Number(v||0)/60)+' ساعت و '+(Number(v||0)%60)+' دقیقه'
const weekdays=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه']
const status=s=>({present:'حاضر',late:'با تأخیر',completed:'خروج ثبت‌شده',corrected:'اصلاح‌شده',incomplete:'ناقص'})[s]||s
const submitSchedule=()=>scheduleForm.post(route('portal.staff-attendance.schedules.store'),{onSuccess:()=>scheduleForm.reset('staff_user_id','start_time','end_time','break_minutes','grace_minutes','effective_until')})
const submitLeave=()=>leaveForm.post(route('portal.staff-attendance.leaves.store'),{onSuccess:()=>leaveForm.reset('reason')})
const submitHoliday=()=>holidayForm.post(route('portal.staff-attendance.holidays.store'),{onSuccess:()=>holidayForm.reset('name')})
const actionDialog=reactive({open:false,title:'',description:'',fields:[],errors:{},processing:false,submit:null})
const closeAction=()=>{if(!actionDialog.processing)actionDialog.open=false}
const submitAction=values=>{if(typeof actionDialog.submit!=='function')return;actionDialog.processing=true;actionDialog.submit(values,{preserveScroll:true,onSuccess:()=>{actionDialog.open=false;actionDialog.errors={}},onError:errors=>{actionDialog.errors=errors||{}},onFinish:()=>{actionDialog.processing=false}})}
const decideLeave=(leave,decision)=>Object.assign(actionDialog,{open:true,title:decision==='approved'?'تأیید درخواست مرخصی':'رد درخواست مرخصی',description:'توضیح مدیر اختیاری است و در سابقه درخواست نگهداری می‌شود.',errors:{},processing:false,fields:[{key:'decision_note',label:'توضیح مدیر',type:'textarea',maxlength:2000}],submit:(v,cb)=>router.patch(route('portal.staff-attendance.leaves.decision',leave.id),{decision,decision_note:v.decision_note||null},cb)})

const removeHoliday=holiday=>{if(window.confirm('تعطیلی ثبت‌شده حذف شود؟'))router.delete(route('portal.staff-attendance.holidays.destroy',holiday.id))}
const checkIn=()=>router.post(route('portal.staff-attendance.check-in'),{organization_id:organizationId.organization_id,clinic_id:organizationId.clinic_id})
const checkOut=()=>router.post(route('portal.staff-attendance.check-out'),{organization_id:organizationId.organization_id,clinic_id:organizationId.clinic_id})
const localDateTime=value=>value?String(value).replace(' ','T').slice(0,16):''
const correct=row=>Object.assign(actionDialog,{open:true,title:'اصلاح سابقه حضور و غیاب',description:'زمان‌های ورود و خروج را اصلاح کنید. علت اصلاح باید حداقل ۸ نویسه باشد.',errors:{},processing:false,fields:[{key:'reason',label:'علت اصلاح',type:'textarea',required:true,maxlength:2000},{key:'check_in_at',label:'زمان ورود (خالی = بدون ورود)',type:'datetime-local',value:localDateTime(row.check_in_at)},{key:'check_out_at',label:'زمان خروج (خالی = بدون خروج)',type:'datetime-local',value:localDateTime(row.check_out_at)}],submit:(v,cb)=>{if(String(v.reason||'').trim().length<8){actionDialog.errors={reason:'علت اصلاح باید حداقل ۸ نویسه باشد.'};actionDialog.processing=false;return}router.patch(route('portal.staff-attendance.correct',row.id),{check_in_at:v.check_in_at||null,check_out_at:v.check_out_at||null,reason:String(v.reason).trim()},cb)}})
</script>
<template><PortalLayout :doctor="doctor"><main dir="rtl" class="mx-auto max-w-7xl space-y-5 p-3 sm:p-5">
<header class="rounded-3xl bg-gradient-to-l from-slate-950 to-indigo-800 p-6 text-white"><p class="text-xs font-bold text-indigo-200">PRONEEX · HUMAN RESOURCES</p><h1 class="mt-2 text-2xl font-black">حضور و غیاب کارکنان</h1><p class="mt-2 text-sm text-white/80">ثبت ورود و خروج، برنامه کاری، محاسبه تأخیر و گزارش قابل حسابرسی.</p></header>
<section class="grid grid-cols-2 gap-3 lg:grid-cols-5"><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">روزهای ثبت‌شده</p><b class="mt-2 block text-2xl">{{summary.days_recorded}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">روزهای دارای تأخیر</p><b class="mt-2 block text-2xl text-amber-600">{{summary.late_days}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">ساعات کار ثبت‌شده</p><b class="mt-2 block text-lg">{{minutes(summary.worked_minutes)}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">روزهای بدون خروج</p><b class="mt-2 block text-2xl">{{summary.incomplete_days}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">غیبت‌های محاسبه‌شده</p><b class="mt-2 block text-2xl text-rose-600">{{summary.absent_days}}</b></article></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">ثبت حضور امروز</h2><div class="mt-3 grid gap-2 sm:grid-cols-3"><select v-model="organizationId.organization_id" class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select><select v-model="organizationId.clinic_id" class="rounded-xl border-slate-300 text-sm"><option value="">انتخاب شعبه</option><option v-for="c in activeOrg?.clinics||[]" :key="c.id" :value="c.id">{{c.name}}</option></select><div class="flex gap-2"><button v-if="!todayRecord?.check_in_at" @click="checkIn" :disabled="!organizationId.clinic_id" class="flex-1 rounded-xl bg-teal-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-40">ثبت ورود</button><button v-else-if="!todayRecord?.check_out_at" @click="checkOut" class="flex-1 rounded-xl bg-indigo-700 px-4 py-2 text-sm font-bold text-white">ثبت خروج</button><span v-else class="flex-1 rounded-xl bg-emerald-50 p-2 text-center text-sm font-bold text-emerald-700">حضور امروز تکمیل شد</span></div></div><p v-if="todayRecord" class="mt-3 text-xs text-slate-500">ورود: {{fmt(todayRecord.check_in_at)}} · خروج: {{fmt(todayRecord.check_out_at)}} · وضعیت: {{status(todayRecord.status)}}</p><p class="mt-3 text-xs leading-6 text-slate-500">ثبت ورود و خروج بر اساس ساعت مجموعه انجام می‌شود. این سامانه مکان زنده یا مسیر رفت‌وآمد کارکنان را ذخیره نمی‌کند.</p></section>
<section v-if="canManage" class="rounded-2xl border bg-white p-4"><h2 class="font-black">تعریف برنامه کاری هفتگی</h2><form @submit.prevent="submitSchedule" class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><select v-model="scheduleForm.organization_id" class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations.filter(x=>x.can_manage)" :key="o.id" :value="o.id">{{o.name}}</option></select><select v-model="scheduleForm.clinic_id" required class="rounded-xl border-slate-300 text-sm"><option value="">شعبه</option><option v-for="c in scheduleOrg?.clinics||[]" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="scheduleForm.staff_user_id" required class="rounded-xl border-slate-300 text-sm"><option value="">کارمند</option><option v-for="m in members.filter(x=>String(x.organization_id)===String(scheduleForm.organization_id))" :key="m.user_id" :value="m.user_id">{{m.name}} {{m.family||''}}</option></select><select v-model.number="scheduleForm.weekday" class="rounded-xl border-slate-300 text-sm"><option v-for="(d,i) in weekdays" :key="i" :value="i">{{d}}</option></select><input v-model="scheduleForm.start_time" type="time" required class="rounded-xl border-slate-300 text-sm"><input v-model="scheduleForm.end_time" type="time" required class="rounded-xl border-slate-300 text-sm"><input v-model.number="scheduleForm.break_minutes" type="number" min="0" max="240" placeholder="استراحت (دقیقه)" class="rounded-xl border-slate-300 text-sm"><input v-model.number="scheduleForm.grace_minutes" type="number" min="0" max="120" placeholder="مهلت تأخیر (دقیقه)" class="rounded-xl border-slate-300 text-sm"><label class="text-xs text-slate-500">شروع اعتبار<input v-model="scheduleForm.effective_from" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label><label class="text-xs text-slate-500">پایان اعتبار (اختیاری)<input v-model="scheduleForm.effective_until" type="date" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label><button :disabled="scheduleForm.processing" class="rounded-xl bg-slate-900 p-3 text-sm font-bold text-white sm:col-span-2 lg:col-span-4">ثبت برنامه کاری</button></form></section>
<section class="rounded-2xl border bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="font-black">برنامه‌های فعال</h2><span class="text-xs text-slate-500">{{schedules.length}} برنامه</span></div><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[620px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">شعبه</th><th class="p-3">روز</th><th class="p-3">ساعت</th><th class="p-3">استراحت</th><th class="p-3">مهلت تأخیر</th></tr></thead><tbody><tr v-for="s in schedules" :key="s.id" class="border-t"><td class="p-3">{{s.staff_name}} {{s.staff_family||''}}</td><td class="p-3">{{s.clinic_name}}</td><td class="p-3">{{weekdays[s.weekday]}}</td><td class="p-3">{{s.start_time.slice(0,5)}} تا {{s.end_time.slice(0,5)}}</td><td class="p-3">{{s.break_minutes}} دقیقه</td><td class="p-3">{{s.grace_minutes}} دقیقه</td></tr><tr v-if="!schedules.length"><td colspan="6" class="p-5 text-center text-slate-400">برنامه‌ای تعریف نشده است.</td></tr></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="font-black">گزارش حضور و غیاب</h2><input :value="month" type="month" @change="e=>router.get(route('portal.staff-attendance.index'),{month:e.target.value},{preserveState:true})" class="rounded-xl border-slate-300 text-sm"></div><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[760px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">تاریخ</th><th class="p-3">کارمند</th><th class="p-3">شعبه</th><th class="p-3">ورود</th><th class="p-3">خروج</th><th class="p-3">تأخیر</th><th class="p-3">کارکرد</th><th class="p-3">وضعیت</th><th v-if="canManage" class="p-3">اصلاح</th></tr></thead><tbody><tr v-for="a in attendances" :key="a.id" class="border-t"><td class="p-3">{{a.work_date}}</td><td class="p-3">{{a.staff_name}} {{a.staff_family||''}}</td><td class="p-3">{{a.clinic_name}}</td><td class="p-3">{{fmt(a.check_in_at)}}</td><td class="p-3">{{fmt(a.check_out_at)}}</td><td class="p-3">{{a.minutes_late}} دقیقه</td><td class="p-3">{{minutes(a.minutes_worked)}}</td><td class="p-3">{{status(a.status)}}</td><td v-if="canManage" class="p-3"><button v-if="a.can_correct" @click="correct(a)" class="rounded-lg bg-amber-100 px-3 py-2 text-amber-800">اصلاح با ثبت علت</button></td></tr><tr v-if="!attendances.length"><td :colspan="canManage?9:8" class="p-6 text-center text-slate-400">برای این ماه سابقه‌ای ثبت نشده است.</td></tr></tbody></table></div></section>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-xs leading-6 text-amber-950"><b>نکته محاسباتی:</b> تأخیر فقط در روزهایی محاسبه می‌شود که برنامه کاری معتبر برای همان شعبه و کارمند تعریف شده باشد. غیبت خودکار از روی نبودن رکورد استنتاج نمی‌شود؛ برای گزارش غیبت قطعی باید برنامه کاری و تقویم تعطیلات نیز لحاظ شوند. اصلاح سوابق فقط برای مالک مجموعه مجاز است و علت و مقادیر قبل و بعد در دفتر رویدادهای حسابرسی نگهداری می‌شوند.</section>
<section v-if="absenceRows.length" class="rounded-2xl border border-rose-200 bg-rose-50 p-4"><h2 class="font-black text-rose-900">غیبت‌های محاسبه‌شده بر اساس برنامه کاری</h2><p class="mt-1 text-xs text-rose-800">این فهرست فقط روزهای کاری گذشته یا شیفت پایان‌یافته را نشان می‌دهد که حضور ثبت نشده و مرخصی تأییدشده یا تعطیلی برای آن وجود ندارد.</p><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[560px] text-right text-xs"><thead><tr><th class="p-2">تاریخ</th><th class="p-2">کارمند</th><th class="p-2">شعبه</th></tr></thead><tbody><tr v-for="(a,i) in absenceRows" :key="i" class="border-t border-rose-200"><td class="p-2">{{a.work_date}}</td><td class="p-2">{{a.staff_name}} {{a.staff_family||''}}</td><td class="p-2">{{a.clinic_name}}</td></tr></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">درخواست مرخصی و مأموریت</h2><form @submit.prevent="submitLeave" class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><select v-model="leaveForm.organization_id" class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select><select v-model="leaveForm.clinic_id" required class="rounded-xl border-slate-300 text-sm"><option value="">شعبه</option><option v-for="c in leaveOrg?.clinics||[]" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="leaveForm.leave_type" class="rounded-xl border-slate-300 text-sm"><option value="annual">مرخصی استحقاقی</option><option value="sick">مرخصی استعلاجی</option><option value="unpaid">مرخصی بدون حقوق</option><option value="mission">مأموریت</option></select><label class="text-xs text-slate-500">از تاریخ<input v-model="leaveForm.start_date" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label><label class="text-xs text-slate-500">تا تاریخ<input v-model="leaveForm.end_date" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label><input v-model="leaveForm.reason" required minlength="5" placeholder="علت / توضیحات درخواست" class="rounded-xl border-slate-300 text-sm"><button :disabled="leaveForm.processing" class="rounded-xl bg-indigo-700 p-3 text-sm font-bold text-white sm:col-span-2 lg:col-span-3">ثبت درخواست برای تأیید</button></form><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[760px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">نوع</th><th class="p-3">بازه</th><th class="p-3">شعبه</th><th class="p-3">وضعیت</th><th class="p-3">توضیحات</th><th v-if="canManage" class="p-3">تصمیم</th></tr></thead><tbody><tr v-for="l in leaveRequests" :key="l.id" class="border-t"><td class="p-3">{{l.staff_name}} {{l.staff_family||''}}</td><td class="p-3">{{({annual:'استحقاقی',sick:'استعلاجی',unpaid:'بدون حقوق',mission:'مأموریت'})[l.leave_type]}}</td><td class="p-3">{{l.start_date}} تا {{l.end_date}}</td><td class="p-3">{{l.clinic_name}}</td><td class="p-3">{{({pending:'در انتظار',approved:'تأییدشده',rejected:'ردشده'})[l.status]||l.status}}</td><td class="p-3">{{l.reason}}<p v-if="l.decision_note" class="mt-1 text-slate-500">{{l.decision_note}}</p></td><td v-if="canManage" class="p-3"><div v-if="l.can_decide&&l.status==='pending'" class="flex gap-1"><button @click="decideLeave(l,'approved')" class="rounded-lg bg-emerald-700 px-2 py-2 text-white">تأیید</button><button @click="decideLeave(l,'rejected')" class="rounded-lg bg-rose-700 px-2 py-2 text-white">رد</button></div></td></tr><tr v-if="!leaveRequests.length"><td :colspan="canManage?7:6" class="p-5 text-center text-slate-400">درخواستی برای این ماه ثبت نشده است.</td></tr></tbody></table></div></section>
<section v-if="canManage" class="rounded-2xl border bg-white p-4"><h2 class="font-black">تعطیلات اختصاصی مجموعه</h2><form @submit.prevent="submitHoliday" class="mt-3 grid gap-2 sm:grid-cols-3"><select v-model="holidayForm.organization_id" required class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations.filter(x=>x.can_manage)" :key="o.id" :value="o.id">{{o.name}}</option></select><input v-model="holidayForm.holiday_date" type="date" required class="rounded-xl border-slate-300 text-sm"><input v-model="holidayForm.name" required maxlength="160" placeholder="عنوان تعطیلی" class="rounded-xl border-slate-300 text-sm"><button :disabled="holidayForm.processing" class="rounded-xl bg-slate-900 p-3 text-sm font-bold text-white sm:col-span-3">ثبت تعطیلی</button></form><div class="mt-3 space-y-2"><div v-for="h in holidays" :key="h.id" class="flex items-center justify-between gap-2 rounded-xl bg-slate-50 p-3 text-xs"><span><b>{{h.holiday_date}}</b> · {{h.name}}</span><button v-if="h.can_delete" @click="removeHoliday(h)" class="rounded-lg bg-rose-100 px-3 py-2 text-rose-700">حذف</button></div><p v-if="!holidays.length" class="text-xs text-slate-400">تعطیلی اختصاصی ثبت نشده است.</p></div></section>
<section v-if="auditEvents.length" class="rounded-2xl border bg-white p-4"><h2 class="font-black">ردپای حسابرسی حضور و غیاب</h2><div class="mt-3 space-y-2"><article v-for="event in auditEvents" :key="event.id" class="rounded-xl bg-slate-50 p-3 text-xs"><div class="flex flex-wrap justify-between gap-2"><b>{{event.staff_name}} {{event.staff_family||''}} · {{({check_in:'ثبت ورود',check_out:'ثبت خروج',manager_correction:'اصلاح توسط مدیر'})[event.event_type]||event.event_type}}</b><span class="text-slate-500">{{new Date(String(event.created_at).replace(' ','T')).toLocaleString('fa-IR')}}</span></div><p class="mt-1 text-slate-600">ثبت‌کننده: {{event.actor_name||'حساب حذف‌شده'}} {{event.actor_family||''}}</p><p v-if="event.reason" class="mt-1 text-amber-800">علت اصلاح: {{event.reason}}</p></article></div></section><ActionDialog :open="actionDialog.open" :title="actionDialog.title" :description="actionDialog.description" :fields="actionDialog.fields" :errors="actionDialog.errors" :processing="actionDialog.processing" @close="closeAction" @submit="submitAction" /></main></PortalLayout></template>
